#include<bits/stdc++.h>
using namespace std;
int s,ans=-1;
int num[1005];
int solve(int x){
	if(num[x]) return num[x];
	int sum=1;
	for(int i=2;i*i<=x;i++){
		if(x%i==0){
			sum+=i;
			if(i!=x/i) sum+=x/i;
		}
	}
	return num[x]=sum;
}
void dfs(int x,int y,int z){
	if(x==0||y+z>s){
		ans=max(ans,z);
		return; 
	}
	dfs(x-1,y,z);
	dfs(x-1,y+x,z+solve(x));
}
int main(){
	ios::sync_with_stdio(0);
	cin.tie(0);cout.tie(0);
	cin>>s;
	dfs(s,0,0);
	cout<<ans+1;
	return 0;
}
